remediations.Detection:
try {
    $free = [math]::Round((Get-PSDrive -Name C).Free / 1GB, 1)
    if ($free -lt 10) { Write-Output "Nur $free GB frei"; exit 1 }
    Write-Output "$free GB frei"
    exit 0
} catch { Write-Output "Fehler: $($_.Exception.Message)"; exit 0 }

remediations.Remediation:
try {
    $before = (Get-PSDrive -Name C).Free
    Get-ChildItem -Path "$env:windir\Temp" -Recurse -Force -ErrorAction SilentlyContinue |
        Where-Object { -not $_.PSIsContainer -and $_.LastWriteTime -lt (Get-Date).AddDays(-7) } |
        Remove-Item -Force -ErrorAction SilentlyContinue
    try { Delete-DeliveryOptimizationCache -Force -ErrorAction Stop } catch { }
    $gain = [math]::Round(((Get-PSDrive -Name C).Free - $before) / 1GB, 1)
    $free = [math]::Round((Get-PSDrive -Name C).Free / 1GB, 1)
    Write-Output "$gain GB freigegeben, jetzt $free GB frei"
    exit 0
} catch { Write-Output "Fehler: $($_.Exception.Message)"; exit 1 }

remediations.Detection:
$s = Get-Service -Name W32Time -ErrorAction SilentlyContinue
if (-not $s) { Write-Output 'W32Time fehlt'; exit 0 }
$mode = (Get-CimInstance Win32_Service -Filter "Name='W32Time'").StartMode
if ($s.Status -ne 'Running' -or $mode -ne 'Auto') { Write-Output "W32Time: $($s.Status), Start $mode"; exit 1 }
Write-Output 'W32Time laeuft'
exit 0

remediations.Remediation:
try {
    Set-Service -Name W32Time -StartupType Automatic
    Start-Service -Name W32Time
    & w32tm.exe /resync /force | Out-Null
    Write-Output 'W32Time gestartet und synchronisiert'
    exit 0
} catch { Write-Output "Fehler: $($_.Exception.Message)"; exit 1 }

try {
    Set-Service -Name wuauserv -StartupType Manual
    Write-Output 'Windows Update wieder aktiviert (Manuell)'
    exit 0
} catch { Write-Output "Fehler: $($_.Exception.Message)"; exit 1 }

remediations.Detection:
try {
    $v = Get-BitLockerVolume -MountPoint 'C:' -ErrorAction Stop
    if ($v.ProtectionStatus -ne 'On') { Write-Output "BitLocker C: $($v.ProtectionStatus), $($v.VolumeStatus)"; exit 1 }
    Write-Output "BitLocker C: an ($($v.EncryptionMethod))"
    exit 0
} catch { Write-Output "Nicht lesbar: $($_.Exception.Message)"; exit 0 }
